// The raw page spelling and decoded check spelling must spend the same entire
// physical suffix budget. A larger decoded delta belongs to another reading.
func agreementPairedRawP1Failure(r *agreementRawP1Declaration, f *agreementFailure, failures []agreementFailure) (*agreementFailure, bool) {
	if r == nil || f == nil || !r.Equation || !strings.HasSuffix(r.Target, "\\") || len(r.Changes) == 0 || f.Property != "P1" || f.Identity != "citation-occurrences" || f.Direction != "judge-only" || f.Tuple != (agreementCitation{Target: strings.TrimSuffix(r.Target, "\\")}) || f.Multiplicity != len(r.Changes) || f.Fragment != "" || f.Cut != "" || f.PagePresent || f.JudgeAccepted || f.ExcerptFound || !maps.Equal(agreementMixedCurrent(failures), r.Signatures) {
		return nil, false
	}
	var raw, normalized *agreementFailure
	for i := range failures {
		current := &failures[i]
		if agreementSignature(current) == r.Selected {
			if raw != nil {
				return nil, false
			}
			raw = current
		}
		if agreementSignature(current) == agreementSignature(f) {
			if normalized != nil {
				return nil, false
			}
			normalized = current
		}
	}
	if raw == nil || normalized == nil || raw.Property != "P1" || raw.Identity != "citation-occurrences" || raw.Direction != "page-only" || raw.Tuple != (agreementCitation{Target: r.Target}) || raw.Multiplicity != f.Multiplicity || raw.Fragment != "" || raw.Cut != "" || raw.PagePresent || raw.JudgeAccepted || raw.ExcerptFound {
		return nil, false
	}
	return raw, true
}

func agreementPairedRawP1Difference(c agreementCase, f *agreementFailure, html string, page *agreementHTML, diagnostics []render.Diagnostic, failures []agreementFailure) (kind, authority, wrong string) {
	if f == nil || page == nil || c.Title != "" || len(c.Companions) != 0 || f.Property != "P1" || f.Direction != "judge-only" {
		return "", "", ""
	}
	records := agreementRawP1Declarations()
	matches := 0
	var owner *agreementRawP1Declaration
	var counterpart *agreementFailure
	for i := range records {
		r := &records[i]
		if r.Body != c.Body || r.Target != f.Tuple.Target+"\\" {
			continue
		}
		raw, valid := agreementPairedRawP1Failure(r, f, failures)
		if !valid {
			continue
		}
		matches++
		owner, counterpart = r, raw
	}
	if matches != 1 || owner == nil {
		return "", "", ""
	}
	kind, authority, wrong = agreementRawP1Difference(c, counterpart, html, page, diagnostics, failures)
	if kind != "debt" || authority != "#1011 stage 3" || wrong != "page" {
		return "", "", ""
	}
	return kind, authority, wrong
}

