func TestAgreementPairedRawP1WholeSource(t *testing.T) {
	records, pins := agreementRawP1Declarations(), agreementPairedRawP1Pins(t)
	if len(records) != len(pins) {
		t.Fatal("caught: whole raw suffix pair source set")
	}
	accepted := 0
	for i := range records {
		r, pin := &records[i], pins[i]
		t.Run(pin.Case, func(t *testing.T) {
			if r.Case != pin.Case || fmt.Sprintf("%x", sha256.Sum256([]byte(r.Body))) != pin.SHA256 || r.Selected != pin.Raw {
				t.Fatal("caught: raw suffix pair original case bytes and signature")
			}
			raw, page, failures := agreementProseP0Failures(t, r.Body)
			if raw.HTML != r.HTML || !cmp.Equal(page, r.Page) || !cmp.Equal(raw.Diagnostics, r.Diagnostics) || !maps.Equal(agreementMixedCurrent(failures), r.Signatures) {
				t.Fatal("caught: raw suffix pair complete current public ledgers")
			}
			count := 0
			for fi := range failures {
				f := &failures[fi]
				k, a, w := agreementPairedRawP1Difference(agreementCase{Body: r.Body}, f, raw.HTML, &page, raw.Diagnostics, failures)
				if k == "" {
					continue
				}
				count++
				if !pin.Paired || agreementSignature(f) != pin.Normalized || k != "debt" || a != "#1011 stage 3" || w != "page" {
					t.Fatal("caught: raw suffix pair exact signed public owner")
				}
			}
			if count != 0 && !pin.Paired || count != 1 && pin.Paired {
				t.Fatal("caught: raw suffix pair complete acceptance and refusal set")
			}
			accepted += count
		})
	}
	if accepted != 97 {
		t.Fatal("caught: whole raw suffix pair budget", accepted)
	}
}

func TestAgreementPairedRawP1Refusals(t *testing.T) {
	records, pins := agreementRawP1Declarations(), agreementPairedRawP1Pins(t)
	for i := range records {
		r, pin := &records[i], pins[i]
		if !pin.Paired {
			continue
		}
		t.Run(pin.Case, func(t *testing.T) {
			var selected *agreementFailure
			for fi := range r.Before {
				if agreementSignature(&r.Before[fi]) == pin.Normalized {
					selected = &r.Before[fi]
				}
			}
			if selected == nil {
				t.Fatal("caught: raw suffix pair selected original")
			}
			refuse := func(c agreementCase, f *agreementFailure, html string, page *agreementHTML, diagnostics []render.Diagnostic, failures []agreementFailure) {
				t.Helper()
				if k, a, w := agreementPairedRawP1Difference(c, f, html, page, diagnostics, failures); k != "" || a != "" || w != "" {
					t.Fatal("caught: raw suffix pair borrowed changed source or whole public ledger")
				}
			}
			c := agreementCase{Body: r.Body}
			refuse(c, nil, r.HTML, &r.Page, r.Diagnostics, r.Before)
			refuse(c, selected, r.HTML, nil, r.Diagnostics, r.Before)
			changed := c
			changed.Body += "\n"
			refuse(changed, selected, r.HTML, &r.Page, r.Diagnostics, r.Before)
			changed = c
			changed.Title = "same body, different note"
			refuse(changed, selected, r.HTML, &r.Page, r.Diagnostics, r.Before)
			changed = c
			changed.Companions = capturedBodies{"Notes/Other.md": "words"}
			refuse(changed, selected, r.HTML, &r.Page, r.Diagnostics, r.Before)
			refuse(c, selected, r.HTML+" ", &r.Page, r.Diagnostics, r.Before)
			page := r.Page
			page.Citations = slices.Clone(r.Page.Citations)
			page.Citations = append(page.Citations, agreementCitation{Target: "unowned"})
			refuse(c, selected, r.HTML, &page, r.Diagnostics, r.Before)
			diags := slices.Clone(r.Diagnostics)
			diags = append(diags, render.Diagnostic{Target: "unowned"})
			refuse(c, selected, r.HTML, &r.Page, diags, r.Before)
			pool := slices.Clone(r.Before)
			pool = append(pool, agreementFailure{Property: "P1", Identity: "citation-occurrences", Tuple: agreementCitation{Target: "unowned"}, Direction: "judge-only", Multiplicity: 1})
			refuse(c, selected, r.HTML, &r.Page, r.Diagnostics, pool)
			pool = nil
			for _, f := range r.Before {
				if agreementSignature(&f) != r.Selected {
					pool = append(pool, f)
				}
			}
			refuse(c, selected, r.HTML, &r.Page, r.Diagnostics, pool)
			for _, alter := range []func(*agreementFailure){
				func(f *agreementFailure) { f.Property = "P2" }, func(f *agreementFailure) { f.Identity = "other" }, func(f *agreementFailure) { f.Direction = "page-only" }, func(f *agreementFailure) { f.Tuple.Target += "x" }, func(f *agreementFailure) { f.Tuple.SourceRole = "display" }, func(f *agreementFailure) { f.Tuple.Section = "part" }, func(f *agreementFailure) { f.Tuple.State = "wikilink-broken" }, func(f *agreementFailure) { f.Multiplicity++ }, func(f *agreementFailure) { f.Multiplicity = 0 }, func(f *agreementFailure) { f.Fragment = "a" }, func(f *agreementFailure) { f.Cut = "words" }, func(f *agreementFailure) { f.PagePresent = true }, func(f *agreementFailure) { f.JudgeAccepted = true }, func(f *agreementFailure) { f.ExcerptFound = true },
			} {
				f := *selected
				alter(&f)
				refuse(c, &f, r.HTML, &r.Page, r.Diagnostics, r.Before)
			}
		})
	}
}
